css:
& { padding:0; gap:0; overflow:hidden; isolation:isolate; }
.st-photo { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:-3; }
.st-shade { position:absolute; inset:0; z-index:-2; background:linear-gradient(90deg,var(--bg),color-mix(in srgb,var(--bg) 90%,transparent) 28%,color-mix(in srgb,var(--bg) 20%,transparent) 74%),linear-gradient(0deg,color-mix(in srgb,var(--bg) 95%,transparent),transparent 70%); }
.st-head { position:absolute; left:100px; top:82px; width:1350px; }
.st-kicker { font:500 22px/1.3 var(--font-mono,var(--mono)); letter-spacing:.13em; text-transform:uppercase; color:var(--accent); }
.st-head h2 { font-family:var(--font-display,var(--font)); font-size:76px; line-height:1.06; max-width:27ch; margin:22px 0 0; text-wrap:balance; }
.st-head p:empty,.st-head h2:empty { display:none; }
.st-intro { font-size:28px; color:var(--muted); line-height:1.4; max-width:53ch; margin-top:24px!important; }
.st-items { list-style:none; padding:0; margin:0; }
.st-items li { opacity:1!important; transform:none!important; }
.st-items li b { display:block; font-weight:650; line-height:1.14; text-wrap:balance; overflow-wrap:anywhere; }
.st-items li span { display:block; line-height:1.4; overflow-wrap:anywhere; }
.st-endnote { position:absolute; left:100px; right:100px; bottom:95px; font-size:32px; line-height:1.3; color:var(--ink); opacity:0; transition:opacity .65s; max-width:58ch; }
&:has([data-template-end].in) .st-endnote,&:has([data-template-end]:not([data-step])) .st-endnote { opacity:1; }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&[data-body-motion="none"] * { transition:none!important; }
@media (prefers-reduced-motion:reduce) { & * { transition:none!important; animation:none!important; } }
.gl-layers { position:absolute; left:950px; top:330px; width:790px; height:570px; perspective:1100px; }
.gl-layer { position:absolute; inset:0; border:2px solid color-mix(in srgb,var(--accent) 30%,transparent); border-radius:50%; transform:rotateX(54deg) rotateZ(-25deg); opacity:.18; transition:transform .9s cubic-bezier(.2,.8,.2,1),opacity .7s,border-color .7s,box-shadow .7s; background:repeating-linear-gradient(90deg,transparent 0 90px,color-mix(in srgb,var(--accent) 15%,transparent) 91px 92px),repeating-linear-gradient(0deg,transparent 0 90px,color-mix(in srgb,var(--accent) 15%,transparent) 91px 92px); }
.gl-two { inset:60px 60px; }.gl-three { inset:120px 120px; }.gl-four { inset:180px 180px; }
.gl-core { position:absolute; left:calc(50% - 10px); top:calc(50% - 10px); width:20px; height:20px; border-radius:50%; background:var(--accent); box-shadow:0 0 45px var(--accent); }
.gl-items { position:absolute; left:100px; top:390px; width:740px; display:grid; gap:22px; counter-reset:layer; }
.gl-items li { position:relative; padding-left:65px; min-height:76px; counter-increment:layer; transition:color .6s; }
.gl-items li::before { content:counter(layer,decimal-leading-zero); position:absolute; top:3px; left:0; font:24px/1.3 var(--font-mono,var(--mono)); color:var(--muted); }
.gl-items li b { font-size:35px; color:var(--muted); transition:color .6s; }
.gl-items li span { margin-top:12px; font-size:27px; max-width:39ch; color:var(--muted); max-height:0; opacity:0; overflow:hidden; transition:max-height .6s,opacity .6s; }
.gl-items li.step-current b { color:var(--accent); }.gl-items li.step-current::before { color:var(--accent); }
.gl-items li.step-current span { max-height:140px; opacity:1; color:var(--ink); }
&:has(.gl-items li:nth-child(1).step-current) .gl-layer:nth-child(1) { opacity:1; border-color:var(--accent); transform:rotateX(30deg) rotateZ(-12deg) translateY(-35px); box-shadow:0 0 50px color-mix(in srgb,var(--accent) 20%,transparent),inset 0 0 50px color-mix(in srgb,var(--accent) 12%,transparent); }
&:has(.gl-items li:nth-child(2).step-current) .gl-layer:nth-child(2) { opacity:1; border-color:var(--accent); transform:rotateX(30deg) rotateZ(-12deg) translateY(-35px); box-shadow:0 0 50px color-mix(in srgb,var(--accent) 20%,transparent),inset 0 0 50px color-mix(in srgb,var(--accent) 12%,transparent); }
&:has(.gl-items li:nth-child(3).step-current) .gl-layer:nth-child(3) { opacity:1; border-color:var(--accent); transform:rotateX(30deg) rotateZ(-12deg) translateY(-35px); box-shadow:0 0 50px color-mix(in srgb,var(--accent) 20%,transparent),inset 0 0 50px color-mix(in srgb,var(--accent) 12%,transparent); }
&:has(.gl-items li:nth-child(4).step-current) .gl-layer:nth-child(4) { opacity:1; border-color:var(--accent); transform:rotateX(30deg) rotateZ(-12deg) translateY(-35px); box-shadow:0 0 50px color-mix(in srgb,var(--accent) 20%,transparent),inset 0 0 50px color-mix(in srgb,var(--accent) 12%,transparent); }
&:has([data-template-end].in), &:has([data-template-end]:not([data-step])) { .gl-layer { opacity:.75; border-color:var(--accent); transform:rotateX(54deg) rotateZ(-25deg); } .gl-items li b { color:var(--ink); } .gl-items li span { max-height:90px; opacity:1; } .gl-items { top:355px; gap:17px; } .gl-items li { min-height:98px; } .gl-items li span { font-size:25px; margin-top:7px; } }

&:not(:has(.gl-items li:nth-child(4))) .gl-four { display:none; }
&:not(:has(.gl-items li:nth-child(3))) .gl-three { display:none; }
